/* Carte de livraison : Madagascar en SVG, projection de Mercator, sans bibliothèque.
   Contour : Natural Earth 1:50m via world-atlas (domaine public). */
(function () {
  'use strict';

  const svg = document.querySelector('[data-map]');
  if (!svg) return;

  const COLORS = ['#21D1CA', '#A181EF', '#F77CB0', '#F77C56', '#F5AE4B', '#67D283'];
  // [ville, longitude, latitude, côté de l'étiquette (r/l), grande ville]
  const CITIES = [
    ['Antsiranana', 49.2917, -12.2787, 'r'], ['Nosy Be', 48.2667, -13.4, 'l'], ['Sambava', 50.1667, -14.2667, 'r'],
    ['Mahajanga', 46.3167, -15.7167, 'l'], ['Toamasina', 49.4023, -18.1492, 'r'], ['Antananarivo', 47.5079, -18.8792, 'r', true],
    ['Antsirabe', 47.0333, -19.8659, 'l'], ['Morondava', 44.3176, -20.2847, 'l'], ['Fianarantsoa', 47.0857, -21.4527, 'l'],
    ['Manakara', 48.0167, -22.15, 'r'], ['Toliara', 43.6667, -23.35, 'l'], ['Taolagnaro', 46.9831, -25.0319, 'r']
  ];
  // Île principale, Nosy Be et Sainte-Marie : [[[lon, lat], …]], …
  const SHAPE = [[[[49.54,-12.43],[49.59,-12.54],[49.64,-12.64],[49.8,-12.88],[49.88,-12.97],[49.94,-13.07],[49.97,-13.27],[50.07,-13.58],[50.18,-14.04],[50.2,-14.51],[50.24,-14.73],[50.31,-14.94],[50.44,-15.15],[50.48,-15.39],[50.41,-15.63],[50.29,-15.86],[50.26,-15.9],[50.21,-15.96],[50.19,-15.96],[50.09,-15.9],[50.02,-15.8],[49.93,-15.57],[49.89,-15.46],[49.86,-15.44],[49.74,-15.45],[49.66,-15.52],[49.65,-15.57],[49.67,-15.7],[49.7,-15.81],[49.71,-15.93],[49.71,-16.08],[49.74,-16.12],[49.79,-16.16],[49.83,-16.26],[49.84,-16.49],[49.81,-16.6],[49.73,-16.7],[49.74,-16.76],[49.77,-16.81],[49.74,-16.85],[49.64,-16.89],[49.6,-16.93],[49.54,-17.03],[49.45,-17.24],[49.44,-17.35],[49.5,-17.67],[49.48,-17.9],[49.36,-18.34],[49.3,-18.54],[49.2,-18.79],[49.06,-19.12],[48.92,-19.53],[48.8,-19.95],[48.71,-20.21],[48.61,-20.46],[48.47,-20.9],[48.35,-21.35],[48.18,-21.84],[47.93,-22.39],[47.91,-22.46],[47.86,-22.75],[47.8,-22.99],[47.74,-23.23],[47.61,-23.63],[47.59,-23.76],[47.56,-23.87],[47.43,-24.12],[47.37,-24.22],[47.34,-24.32],[47.31,-24.44],[47.27,-24.56],[47.18,-24.79],[47.04,-24.98],[46.94,-25.05],[46.73,-25.15],[46.62,-25.17],[46.39,-25.17],[46.16,-25.23],[45.92,-25.34],[45.69,-25.47],[45.6,-25.53],[45.51,-25.56],[45.21,-25.57],[45.11,-25.54],[44.81,-25.33],[44.7,-25.3],[44.47,-25.27],[44.41,-25.25],[44.35,-25.23],[44.26,-25.12],[44.08,-25.02],[44.03,-25],[44.01,-24.93],[43.99,-24.86],[43.94,-24.79],[43.91,-24.64],[43.85,-24.54],[43.69,-24.36],[43.67,-24.3],[43.66,-24.11],[43.66,-23.98],[43.65,-23.74],[43.66,-23.63],[43.72,-23.53],[43.7,-23.42],[43.64,-23.31],[43.62,-23.19],[43.57,-23.08],[43.4,-22.89],[43.36,-22.79],[43.33,-22.69],[43.26,-22.38],[43.26,-22.28],[43.27,-22.05],[43.29,-21.93],[43.33,-21.85],[43.34,-21.79],[43.37,-21.74],[43.41,-21.7],[43.44,-21.65],[43.5,-21.36],[43.58,-21.29],[43.7,-21.25],[43.8,-21.18],[43.86,-21.08],[43.91,-20.87],[44.06,-20.66],[44.12,-20.55],[44.24,-20.38],[44.35,-20.15],[44.38,-20.03],[44.4,-19.92],[44.43,-19.67],[44.45,-19.55],[44.45,-19.43],[44.39,-19.3],[44.24,-19.07],[44.24,-19.03],[44.25,-18.86],[44.23,-18.74],[44.18,-18.62],[44.11,-18.5],[44.04,-18.29],[44.01,-17.93],[44.01,-17.8],[43.99,-17.69],[43.94,-17.58],[43.98,-17.39],[44.42,-16.7],[44.44,-16.62],[44.42,-16.41],[44.43,-16.29],[44.44,-16.24],[44.48,-16.22],[44.55,-16.2],[44.91,-16.17],[44.96,-16.15],[45.05,-16.1],[45.17,-15.98],[45.22,-15.95],[45.27,-15.96],[45.3,-16.01],[45.34,-16.04],[45.48,-15.99],[45.54,-15.98],[45.6,-15.99],[45.63,-15.95],[45.64,-15.88],[45.66,-15.84],[45.7,-15.81],[45.88,-15.8],[46,-15.78],[46.16,-15.74],[46.19,-15.75],[46.31,-15.9],[46.35,-15.92],[46.4,-15.93],[46.44,-15.9],[46.34,-15.81],[46.33,-15.77],[46.33,-15.71],[46.38,-15.6],[46.47,-15.51],[46.68,-15.38],[46.88,-15.23],[46.94,-15.22],[46.99,-15.24],[47.03,-15.42],[47.03,-15.45],[47.06,-15.46],[47.1,-15.43],[47.13,-15.36],[47.13,-15.3],[47.11,-15.24],[47.09,-15.19],[47.09,-15.15],[47.2,-15.04],[47.28,-14.94],[47.32,-14.82],[47.35,-14.77],[47.44,-14.7],[47.46,-14.71],[47.49,-14.76],[47.5,-14.82],[47.48,-14.87],[47.44,-14.93],[47.43,-14.99],[47.48,-15.01],[47.53,-14.99],[47.59,-14.86],[47.67,-14.74],[47.72,-14.68],[47.77,-14.64],[47.87,-14.65],[47.97,-14.67],[47.81,-14.55],[47.77,-14.37],[47.95,-14.07],[47.96,-14],[47.98,-13.98],[47.99,-13.96],[47.9,-13.86],[47.88,-13.81],[47.9,-13.73],[47.94,-13.66],[47.98,-13.61],[48.04,-13.6],[48.09,-13.62],[48.19,-13.71],[48.26,-13.72],[48.34,-13.64],[48.4,-13.54],[48.51,-13.47],[48.62,-13.43],[48.8,-13.27],[48.91,-12.94],[48.92,-12.84],[48.89,-12.72],[48.85,-12.61],[48.79,-12.47],[48.8,-12.44],[48.9,-12.46],[48.93,-12.44],[49.03,-12.32],[49.21,-12.08],[49.26,-12.08],[49.31,-12.12],[49.33,-12.19],[49.37,-12.24],[49.48,-12.35],[49.54,-12.43]]],[[[48.34,-13.36],[48.34,-13.4],[48.21,-13.39],[48.19,-13.26],[48.26,-13.26],[48.27,-13.21],[48.31,-13.2],[48.35,-13.31],[48.34,-13.36]]],[[[49.94,-16.9],[49.82,-17.09],[49.86,-16.93],[49.98,-16.71],[50.02,-16.69],[49.94,-16.9]]]];

  const RAD = Math.PI / 180;
  const merc = (pt) => [pt[0] * RAD, -Math.log(Math.tan(Math.PI / 4 + pt[1] * RAD / 2))];
  const n1 = (v) => v.toFixed(1);
  let first = true;

  function draw() {
    const w = svg.clientWidth, h = svg.clientHeight;
    if (!w || !h) return;
    // Cadre : la carte tient dans le bloc en laissant de la place aux étiquettes.
    const padX = Math.max(84, w * 0.17), padY = 22;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    SHAPE.forEach((poly) => poly.forEach((ring) => ring.forEach((pt) => {
      const m = merc(pt);
      if (m[0] < x0) x0 = m[0]; if (m[0] > x1) x1 = m[0];
      if (m[1] < y0) y0 = m[1]; if (m[1] > y1) y1 = m[1];
    })));
    const bw = w - 2 * padX, bh = h - 2 * padY;
    const k = Math.min(bw / (x1 - x0), bh / (y1 - y0));
    const tx = padX + (bw - k * (x1 - x0)) / 2 - k * x0;
    const ty = padY + (bh - k * (y1 - y0)) / 2 - k * y0;
    const P = (pt) => { const m = merc(pt); return [tx + k * m[0], ty + k * m[1]]; };
    const seg = (a, b) => 'M' + n1(a[0]) + ',' + n1(a[1]) + 'L' + n1(b[0]) + ',' + n1(b[1]);

    const island = SHAPE.map((poly) => poly.map((ring) => 'M' + ring.map((pt) => P(pt).map(n1).join(',')).join('L') + 'Z').join('')).join('');
    let grat = '';
    for (let lon = 40; lon <= 52; lon += 2) grat += seg(P([lon, -28]), P([lon, -10]));
    for (let lat = -28; lat <= -12; lat += 2) grat += seg(P([40, lat]), P([54, lat]));
    let lats = '';
    [-12, -16, -20, -24].forEach((lat) => {
      const y = P([45, lat])[1];
      if (y > 12 && y < h - 6) lats += '<text class="map-lat" x="6" y="' + n1(y - 5) + '">' + Math.abs(lat) + '°S</text>';
    });
    const s = Math.max(5, Math.round(Math.min(w, h) / 78));
    const cities = CITIES.map((c, i) => {
      const xy = P([c[1], c[2]]), col = COLORS[i % COLORS.length], dx = c[3] === 'r' ? 13 : -13, big = !!c[4];
      return '<g transform="translate(' + n1(xy[0]) + ',' + n1(xy[1]) + ')">' +
        '<circle class="map-pulse" r="' + (big ? 7 : 5) + '" fill="none" stroke="' + col + '" stroke-width="1.2" style="animation-delay:' + ((i * 0.37) % 3.2).toFixed(2) + 's"/>' +
        '<circle r="' + (big ? 4 : 3) + '" fill="' + col + '"/>' +
        '<circle r="' + (big ? 1.6 : 1.2) + '" fill="#fff"/>' +
        '<line x1="' + n1(dx * 0.45) + '" x2="' + n1(dx * 0.85) + '" y1="0" y2="0" stroke="rgba(255,255,255,.35)"/>' +
        '<text class="map-lbl' + (big ? ' map-lbl--big' : '') + '" x="' + dx + '" y="3.5" text-anchor="' + (c[3] === 'r' ? 'start' : 'end') + '">' + c[0] + '</text>' +
      '</g>';
    }).join('');

    svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    svg.innerHTML =
      '<defs>' +
        '<linearGradient id="mg-holo" gradientUnits="userSpaceOnUse" x1="0" y1="' + padY + '" x2="' + n1(w * 0.25) + '" y2="' + (h - padY) + '">' +
          '<stop offset="0" stop-color="#21D1CA"/><stop offset=".35" stop-color="#A181EF"/><stop offset=".65" stop-color="#F77CB0"/><stop offset="1" stop-color="#F5AE4B"/>' +
        '</linearGradient>' +
        '<pattern id="mg-dots" width="' + s + '" height="' + s + '" patternUnits="userSpaceOnUse"><circle cx="' + s / 2 + '" cy="' + s / 2 + '" r="' + n1(s * 0.28) + '" fill="#fff"/></pattern>' +
        '<mask id="mg-mask"><rect width="' + w + '" height="' + h + '" fill="url(#mg-dots)"/></mask>' +
        '<clipPath id="mg-island"><path d="' + island + '"/></clipPath>' +
      '</defs>' +
      '<g' + (first ? ' class="map-fade"' : '') + '>' +
        '<path d="' + grat + '" fill="none" stroke="rgba(255,255,255,.07)"/>' + lats +
        '<path d="' + island + '" fill="url(#mg-holo)" opacity=".12"/>' +
        '<rect width="' + w + '" height="' + h + '" fill="url(#mg-holo)" mask="url(#mg-mask)" clip-path="url(#mg-island)"/>' +
        '<path d="' + island + '" fill="none" stroke="rgba(255,255,255,.3)"/>' +
        cities +
      '</g>';
    first = false;
  }

  // Dessine quand la carte approche de l'écran ; met les pulsations en pause hors écran.
  let started = false;
  const start = () => { if (!started) { started = true; draw(); } };
  if ('IntersectionObserver' in window) {
    new IntersectionObserver((es) => {
      const on = es[0].isIntersecting;
      if (on) start();
      svg.classList.toggle('is-paused', !on);
    }, { rootMargin: '300px 0px' }).observe(svg);
  } else {
    start();
  }
  let rt = 0, lastW = 0, lastH = 0;
  window.addEventListener('resize', () => {
    clearTimeout(rt);
    rt = setTimeout(() => {
      if (!started || (svg.clientWidth === lastW && svg.clientHeight === lastH)) return;
      lastW = svg.clientWidth; lastH = svg.clientHeight;
      draw();
    }, 150);
  });
})();
